def _pause(job):
    """The pause switch: LATE_FEES_PAUSE if set (and not empty), else the file.

    The value is parsed as a boolean (1/yes/true/on, 0/no/false/off), so
    LATE_FEES_PAUSE=0 means "not paused". Anything else is an error rather
    than a silent pause.
    """
    raw = os.environ.get("LATE_FEES_PAUSE", "").strip()
    if not raw:
        return job.getboolean("pause", fallback=False)
    value = configparser.ConfigParser.BOOLEAN_STATES.get(raw.lower())
    if value is None:
        raise ValueError(f"LATE_FEES_PAUSE={raw!r} is not a boolean")
    return value


